	for i, o := range c.Objects {
		if o != obj {
			continue
		}

		removed := append(c.Objects[:i], c.Objects[i+1:]...)
		// note - no resize this should be triggered from parent
		c.Objects = removed
		c.layout()
		return
	}
}

