// allStringsValidator validates that the input value is present in a predefined list of strings.
type allStringsValidator struct {
	list []string
}

// Validate checks if the input string is present in the validator's list.
// Returns an error if the string is not found in the list.
func (v *allStringsValidator) Validate(s string) error {
	for _, item := range v.list {
		if item == s {
			return nil
		}
	}
	return fmt.Errorf("value not in allowed list")
}

// NewAllStrings creates a new validator that checks if the input string
// is present in the provided list of allowed strings.
//
// Since: 2.5
func NewAllStrings(list []string) fyne.StringValidator {
	return &allStringsValidator{list: list}
}

