// FromJSONReader creates a new theme from a JSON reader.
// The JSON should contain color and size definitions.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}

	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&raw); err != nil {
		return nil, fmt.Errorf("failed to decode JSON: %w", err)
	}

	theme := &jsonTheme{
		colors: make(map[fyne.ThemeColorName]color.Color),
		sizes:  make(map[fyne.ThemeSizeName]float32),
		fonts:  make(map[fyne.TextStyle]fyne.Resource),
		icons:  make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse colors (generic)
	if colorsRaw, ok := raw["colors"].(map[string]interface{}); ok {
		for name, value := range colorsRaw {
			if hexStr, ok := value.(string); ok {
				c, err := parseHexColor(hexStr)
				if err != nil {
					return nil, fmt.Errorf("invalid color for %s: %w", name, err)
				}
				theme.colors[fyne.ThemeColorName(name)] = c
			}
		}
	}

	// Parse colors-dark
	if colorsRaw, ok := raw["colors-dark"].(map[string]interface{}); ok {
		for name, value := range colorsRaw {
			if hexStr, ok := value.(string); ok {
				c, err := parseHexColor(hexStr)
				if err != nil {
					return nil, fmt.Errorf("invalid color for %s: %w", name, err)
				}
				theme.colors[fyne.ThemeColorName(name)] = c
			}
		}
	}

	// Parse colors-light
	if colorsRaw, ok := raw["colors-light"].(map[string]interface{}); ok {
		for name, value := range colorsRaw {
			if hexStr, ok := value.(string); ok {
				c, err := parseHexColor(hexStr)
				if err != nil {
					return nil, fmt.Errorf("invalid color for %s: %w", name, err)
				}
				theme.colors[fyne.ThemeColorName(name)] = c
			}
		}
	}

	// Parse sizes
	if sizesRaw, ok := raw["sizes"].(map[string]interface{}); ok {
		for name, value := range sizesRaw {
			switch v := value.(type) {
			case float64:
				theme.sizes[fyne.ThemeSizeName(name)] = float32(v)
			case int:
				theme.sizes[fyne.ThemeSizeName(name)] = float32(v)
			default:
				return nil, errors.New(fmt.Sprintf("invalid size type for %s", name))
			}
		}
	}

	// Parse fonts (map of font style to URI)
	if fontsRaw, ok := raw["fonts"].(map[string]interface{}); ok {
		for styleName, value := range fontsRaw {
			if uriStr, ok := value.(string); ok {
				res := fyne.NewStaticResource(styleName, []byte{}) // Placeholder - in real implementation would load from URI
				// Parse text style from string (e.g., "bold", "italic", "monospace")
				style := fyne.TextStyle{}
				switch styleName {
				case "bold":
					style.Bold = true
				case "italic":
					style.Italic = true
				case "monospace":
					style.Monospace = true
				case "bold-italic":
					style.Bold = true
					style.Italic = true
				}
				theme.fonts[style] = res
			}
		}
	}

	// Parse icons (map of icon name to URI)
	if iconsRaw, ok := raw["icons"].(map[string]interface{}); ok {
		for name, value := range iconsRaw {
			if uriStr, ok := value.(string); ok {
				res := fyne.NewStaticResource(name, []byte{}) // Placeholder - in real implementation would load from URI
				theme.icons[fyne.ThemeIconName(name)] = res
			}
		}
	}

	return theme, nil
}

